package com.p1770;

public class LugannaniRice {
    /*
    * How do you approximate Binomial(n, p).cdf(k) without libraries?
    *
    * https://en.wikipedia.org/wiki/Saddlepoint_approximation_method
    *
    * No correctness guaranteed whatsoever.
    */

    // Abramowitz-Stegun erf approximation
    static double erf(double x) {
        double t = 1.0 / (1.0 + 0.3275911 * Math.abs(x));

        double y = 1.0 - (((((1.061405429 * t
                - 1.453152027) * t
                + 1.421413741) * t
                - 0.284496736) * t
                + 0.254829592) * t)
                * Math.exp(-x * x);

        return Math.signum(x) * y;
    }

    static double normalPDF(double x) {
        return Math.exp(-0.5 * x * x) / Math.sqrt(2 * Math.PI);
    }

    static double normalCDF(double x) {
        return 0.5 * (1.0 + erf(x / Math.sqrt(2)));
    }

    static double binomCDF(int n, double p, int k) {

        if (k < 0) return 0.0;
        if (k == 0) return Math.exp(n * Math.log1p(-p));
        if (k >= n) return 1.0;

        double phat = ((double) k) / n;

        // Normal approximation is OK near mean
        if (Math.abs(p - phat) < 1e-8)
            return normalCDF((k + 0.5 - n*p) / Math.sqrt(n*p*(1-p)));

        // w = sign(t) * sqrt(2 * n * KL(phat || p))
        double D = k * (Math.log(phat) - Math.log(p))
                + (n-k) * (Math.log1p(-phat) - Math.log1p(-p));

        double w = Math.copySign(Math.sqrt(2.0 * D), phat - p);

        double var = n * phat * (1.0 - phat);
        double t = Math.log(phat)
                - Math.log1p(-phat)
                - Math.log(p)
                + Math.log1p(-p);

        double u = -Math.expm1(-t) * Math.sqrt(var);

        return Math.min(1.0, Math.max(normalCDF(w) + normalPDF(w) * ((u - w) / (u * w)), 0.0));
    }
}

