package com.p1770;

import net.runelite.client.game.ItemStack;

import java.util.Collection;
import java.util.Map;

public final class P1770DataHandler {
    private final Map<String, Integer> killCounts;
    private final Map<String, Integer> dropCounts;
    private final Map<String, Map<String, Double>> npcItemDropChances;
    private final Map<Integer, String> npcIdResolver;
    private final Map<Integer, String> itemIdResolver;

    public P1770DataHandler(
        Map<String, Integer> killCounts,
        Map<String, Integer> dropCounts,
        Map<String, Map<String, Double>> npcItemDropChances,
        Map<Integer, String> npcIdResolver,
        Map<Integer, String> itemIdResolver
    ) {
        this.killCounts = killCounts;
        this.dropCounts = dropCounts;
        this.npcItemDropChances = npcItemDropChances;
        this.npcIdResolver = npcIdResolver;
        this.itemIdResolver = itemIdResolver;
    }

    public void registerLoot(int npcId, Collection<ItemStack> items) {
        String npcLabel = this.npcIdResolver.get(npcId);
        if (npcLabel != null) {
            this.killCounts.computeIfPresent(npcLabel, (k, v) -> v + 1);
        }

        for (ItemStack item : items) {
            String itemLabel = this.itemIdResolver.get(item.getId());
            if (itemLabel != null) {
                this.dropCounts.computeIfPresent(itemLabel, (k, v) -> v + item.getQuantity());
            }
        }
    }

    public static double chanceBinomialIsAtMost(int n, double p, int m) {
        return LugannaniRice.binomCDF(n, p, m);
    }

    public static double zScoreBinomial(int n, double p, int m) {
       return (m-n*p)*Math.pow(n*p*(1-p), -0.5);
    }

    public String summaryMessage(int npcId) {
        StringBuilder msgBuilder = new StringBuilder();

        String npcLabel = this.npcIdResolver.get(npcId);
        Map<String, Double> dropChances = this.npcItemDropChances.get(npcLabel);
        Integer killCount = this.killCounts.get(npcLabel);

        if ((npcLabel == null) || (dropChances == null) || (killCount == null)) {
            return "";
        }

        msgBuilder.append(String.format("In %d of %s", killCount, npcLabel));

        for (Map.Entry<String, Double> entry : dropChances.entrySet()) {
            String itemLabel = entry.getKey();

            Integer dropCount = this.dropCounts.get(itemLabel);
            if (dropCount == null) {
                continue;
            }

            double dropChance = entry.getValue();

            msgBuilder.append(String.format(
                    ", at %d %s: F=%.3f, z=%.3f",
                    dropCount,
                    itemLabel,
                    chanceBinomialIsAtMost(killCount, dropChance, dropCount),
                    zScoreBinomial(killCount, dropChance, dropCount)
            ));
        }
        msgBuilder.append(".");

        return msgBuilder.toString();
    }
}

package com.p1770;

import com.google.gson.Gson;
import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ServerNpcLoot;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

import java.util.Collection;

@Slf4j
@PluginDescriptor(
	name = "P1770",
	description = "A trivial, supplementary luck-tracker for Bryophyta-like grinds."
)
public class P1770Plugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private P1770Config config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private Gson GSON;

	private P1770DataHandler p1770DataHandler;

	@Subscribe
	public void onServerNpcLoot(final ServerNpcLoot event) {
		final int npcId = event.getComposition().getId();
		final Collection<ItemStack> items = event.getItems();

		this.p1770DataHandler.registerLoot(npcId, items);
		client.addChatMessage(
				ChatMessageType.GAMEMESSAGE, "",
				this.p1770DataHandler.summaryMessage(npcId), null
		);
	}

	@Override
	protected void startUp() {
		this.p1770DataHandler = GSON.fromJson(config.getPluginDataJSON(), P1770DataHandler.class);
	}

	@Override
	protected void shutDown() {
		config.setPluginDataJSON(GSON.newBuilder().setPrettyPrinting().create().toJson(this.p1770DataHandler));
	}

	@Provides
	P1770Config provideConfig(ConfigManager configManager) {
		return configManager.getConfig(P1770Config.class);
	}
}

package com.p1770;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class P1770PluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(P1770Plugin.class);
		RuneLite.main(args);
	}
}
